+pub(crate) struct CollisionHistory {
+    grid: HistGrid,
+    collisions: Collisions,
+    cells: Vec<i64>,
+    cell_ends: Vec<usize>,
+    snaps: Vec<SnapNode>,
+    snap_ends: Vec<usize>,
+    active: ActiveCellCache,
+    lines: Vec<i32>,
+    line_ends: Vec<usize>,
