+impl CollisionHistory {
+    pub(crate) fn new() -> Self {
+        Self {
+            grid: HistGrid::default(),
+            collisions: Collisions::default(),
+            cells: Vec::new(),
+            cell_ends: vec![0, 0],
+            snaps: Vec::new(),
+            snap_ends: vec![0, 0],
+            active: ActiveCellCache::default(),
+            lines: Vec::new(),
+            line_ends: vec![0, 0],
