+    pub(crate) fn clear(&mut self) {
+        self.active.begin_frame();
+        self.grid.clear();
+        self.collisions.clear();
+        self.cells.clear();
+        self.snaps.clear();
+        self.lines.clear();
+        for ends in [
+            &mut self.cell_ends,
+            &mut self.snap_ends,
+            &mut self.line_ends,
+        ] {
+            ends.clear();
+            ends.extend_from_slice(&[0, 0]);
+        }
+    }
