+    #[inline]
+    pub(crate) fn record_collision(&mut self, id: i32, frame: i32) {
+        debug_assert_eq!(frame as usize, self.len());
+        let list = self.collisions.entry(id).or_default();
+        if list.last() != Some(&frame) {
+            list.push(frame);
+            self.lines.push(id);
+        }
+    }
